test('renderInvoiceText with complete invoice (discount, voucher, due, paid)', () => {
  let result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
    terms: 'NET14',
  });
  result = applyVoucher(result.value, { code: 'SPECIAL', amount: 2000 });
  let issued = issueInvoice(result.value, []);
  const totals = invoiceTotals(issued.value);
  issued = recordPayment(issued.value, { amount: Math.floor(totals.total * 0.4), date: '2026-10-02' });

  const text = renderInvoiceText(issued.value);
  const lines = text.split('\n');

  // Check all components present
  assert(text.includes('INV-2026-0001'));
  assert(text.includes('Discount (10%)'));
  assert(text.includes('Voucher (SPECIAL)'));
  assert(text.includes('Due: 2026-10-15'));
  assert(text.includes('Paid:'));

  // Check order: discount after line, voucher before total, due and paid at end
  const discountIdx = lines.findIndex((l) => l.includes('Discount'));
  const voucherIdx = lines.findIndex((l) => l.includes('Voucher'));
  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));
  const dueIdx = lines.findIndex((l) => l.startsWith('Due:'));
  const paidIdx = lines.findIndex((l) => l.startsWith('Paid:'));

  assert(discountIdx > 0); // After line
  assert(voucherIdx < totalIdx); // Before total
  assert(dueIdx > totalIdx); // After total
  assert(paidIdx > dueIdx); // After due
});
ENDTEST
